<script>export let data;</script><section class="page"><div class="eyebrow">ANIMAL HELP</div><h1>Someone nearby may need you.</h1><p class="sub">Community requests for injured animals. PawConnect does not provide medical diagnosis or emergency dispatch.</p><div class="toolbar"><a class="btn primary" href="/help/new">+ Request help</a></div>{#if data.requests.length}<div class="masonry">{#each data.requests as item}<a class="card" href={`/report/${item.id}?kind=help`}><div>{#if item.image_url}<img src={item.image_url} alt={item.title}/>{:else}<div class="image-placeholder">🆘</div>{/if}</div><div class="card-body"><div class="meta"><span>{item.animal_type}</span><span>open</span></div><h3>{item.title}</h3><p>{item.description}</p><small>📍 {item.location} · 🤝 {item.helper_count} helper(s)</small></div></a>{/each}</div>{:else}<div class="empty">No open help requests right now.</div>{/if}</section>
